const crypto = require('crypto');
const secret = $env.WORKBENCH_AUTOMATION_SECRET;
const base = $env.WORKBENCH_BASE_URL;
const endpoint = new URL(base);
const host = endpoint.hostname;
const octets = host.split('.').map(Number);
const ipv4 = /^\d+\.\d+\.\d+\.\d+$/.test(host) && octets.every(x => x >= 0 && x <= 255);
const local = host === 'localhost' || host === '[::1]' || (ipv4 && (octets[0] === 127 || octets[0] === 10 || (octets[0] === 192 && octets[1] === 168) || (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31))) || /^[a-z][a-z0-9-]*$/.test(host) || /\.(local|internal)$/.test(host);
if (!['http:', 'https:'].includes(endpoint.protocol) || endpoint.username || endpoint.password || endpoint.search || endpoint.hash || !local) throw new Error('Local/private workbench endpoint required');
const kind = $env.WORKBENCH_AUTOMATION_KIND || 'audit_summary';
if (!secret || secret.length < 32 || !base) throw new Error('Configure local endpoint and signing secret');
const timestamp = Math.floor(Date.now() / 1000);
const nonce = crypto.randomUUID();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${kind}`).digest('hex');
return [{json: {timestamp, nonce, kind, signature}}];
